def _capture_batch_snapshot(self, tenant: str) -> tuple[str, int]:
    """Copy the tenant's current batch summaries into one new snapshot.

    Returns (snapshot_id, number_of_entries). Zero-entry tenants and
    single-page snapshots need no cursor and therefore no retained state.
    """
    try:
        rows = self._connection.execute(
            "SELECT batch_id, record_count, created_at FROM encrypted_batches "
            "WHERE tenant=? ORDER BY batch_id ASC",
            (tenant,),
        ).fetchall()
    except sqlite3.Error:
        raise storage() from None
    # Validate the captured summaries before persisting or serving them;
    # internal record/event integrity is intentionally not consulted.
    summaries = [self._validated_batch_summary(row) for row in rows]
    snapshot_id = os.urandom(18).hex()
    created_at = datetime.now(timezone.utc).isoformat(timespec="seconds")
    try:
        with self._connection:
            self._connection.execute(
                "INSERT INTO encrypted_batch_list_snapshots "
                "(snapshot_id, tenant, created_at) VALUES (?, ?, ?)",
                (snapshot_id, tenant, created_at),
            )
            self._connection.executemany(
                "INSERT INTO encrypted_batch_list_entries "
                "(snapshot_id, position, batch_id, record_count, created_at) "
                "VALUES (?, ?, ?, ?, ?)",
                [
                    (snapshot_id, position, batch_id, count, batch_created_at)
                    for position, (batch_id, count, batch_created_at) in enumerate(summaries)
                ],
            )
    except sqlite3.Error:
        raise storage() from None
    return snapshot_id, len(summaries)

