def test_listing_is_read_only_and_single_page_persists_nothing(self):
    self.ingest(1)
    for _ in range(3):
        self.assertEqual(self.list_batches()[0], 200)
    raw = self.db()
    try:
        self.assertEqual(
            raw.execute("SELECT COUNT(*) FROM encrypted_batch_list_snapshots")
            .fetchone()[0],
            0,
        )
        self.assertEqual(
            raw.execute("SELECT COUNT(*) FROM encrypted_batch_list_entries")
            .fetchone()[0],
            0,
        )
        table_counts = {
            name: raw.execute(
                "SELECT COUNT(*) FROM " + name
            ).fetchone()[0]
            for name in (
                "encrypted_batches",
                "encrypted_records",
                "encrypted_record_events",
                "encrypted_batch_idempotency_keys",
            )
        }
    finally:
        raw.close()
    # Walking a multi-page listing adds only snapshot bookkeeping rows; the
    # protocol tables keep exactly the counts above.
    for _ in range(4):
        self.ingest(1)
    self.walk("limit=2")
    raw = self.db()
    try:
        for name, count in table_counts.items():
            # Five batches total: the earlier single batch plus four more.
            scale = 5 if name == "encrypted_batches" else None
            actual = raw.execute("SELECT COUNT(*) FROM " + name).fetchone()[0]
            if name == "encrypted_batches":
                self.assertEqual(actual, 5)
            elif name == "encrypted_records":
                self.assertEqual(actual, 5)
            elif name == "encrypted_record_events":
                self.assertEqual(actual, 5)
            else:
                self.assertEqual(actual, count)
    finally:
        raw.close()

